// reverse returns s with its characters in reverse order.
// The returned string has the same length as s.
func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}
```

Notes on the approach:
- It reverses in place over `[]rune`, so it handles Unicode correctly and returns a string with the same length as the input (same characters, reordered).
